from pathlib import Path
Path('system').mkdir(exist_ok=True)
Path('constant').mkdir(exist_ok=True)
Path('system/controlDict').write_text('''FoamFile{format ascii; class dictionary; object controlDict;}
application snappyHexMesh; startFrom startTime; startTime 0; stopAt endTime; endTime 1; deltaT 1; writeControl timeStep; writeInterval 1;
''')
Path('system/blockMeshDict').write_text(f'''FoamFile{{format ascii; class dictionary; object blockMeshDict;}}
scale 1;
vertices (({XMIN} {YMIN} {ZMIN}) ({XMAX} {YMIN} {ZMIN}) ({XMAX} {YMAX} {ZMIN}) ({XMIN} {YMAX} {ZMIN}) ({XMIN} {YMIN} {ZMAX}) ({XMAX} {YMIN} {ZMAX}) ({XMAX} {YMAX} {ZMAX}) ({XMIN} {YMAX} {ZMAX}));
blocks (hex (0 1 2 3 4 5 6 7) (78 28 36) simpleGrading (1 1 1));
edges ();
boundary (
 inlet {{type patch; faces ((0 4 7 3));}}
 outlet {{type patch; faces ((1 2 6 5));}}
 root_wall {{type wall; faces ((0 1 5 4));}}
 far_field {{type patch; faces ((3 7 6 2)(0 3 2 1)(4 5 6 7));}}
);
''')
Path('system/snappyHexMeshDict').write_text('''FoamFile{format ascii; class dictionary; object snappyHexMeshDict;}
castellatedMesh true; snap true; addLayers false;
geometry { wing.stl {type triSurfaceMesh; name wing;} }
castellatedMeshControls {
 maxLocalCells 500000; maxGlobalCells 1000000; minRefinementCells 0; maxLoadUnbalance 0.10; nCellsBetweenLevels 2;
 features (); refinementSurfaces {wing {level (2 2); patchInfo {type wall;}}}
 resolveFeatureAngle 25; refinementRegions {}
 locationInMesh (-0.20 0.20 0.20); allowFreeStandingZoneFaces true;
}
snapControls {nSmoothPatch 3; tolerance 2.0; nSolveIter 50; nRelaxIter 5; nFeatureSnapIter 10; implicitFeatureSnap false; explicitFeatureSnap false; multiRegionFeatureSnap false;}
addLayersControls {relativeSizes true; layers {}; expansionRatio 1.2; finalLayerThickness 0.3; minThickness 0.1; nGrow 0; featureAngle 60; slipFeatureAngle 30; nRelaxIter 3; nSmoothSurfaceNormals 1; nSmoothNormals 3; nSmoothThickness 10; maxFaceThicknessRatio 0.5; maxThicknessToMedialRatio 0.3; minMedialAxisAngle 90; nBufferCellsNoExtrude 0; nLayerIter 50;}
meshQualityControls {#include "meshQualityDict"}
mergeTolerance 1e-6;
''')
Path('system/meshQualityDict').write_text('''maxNonOrtho 70; maxBoundarySkewness 20; maxInternalSkewness 4; maxConcave 80; minVol 1e-15; minTetQuality 1e-30; minArea -1; minTwist 0.02; minDeterminant 0.001; minFaceWeight 0.02; minVolRatio 0.01; minTriangleTwist -1; nSmoothScale 4; errorReduction 0.75; relaxed {maxNonOrtho 75;}
''')
print(Path('system/blockMeshDict').read_text()[:500]); print('mesh dictionaries written')

